//! Every HTTP route, one file per area.
// Generated by scripts/gen.sh from the files in this folder. Never edit: add a file and run `just gen`.

mod devices;
mod folders;
mod logins;
mod mcp;
mod pairing;
mod personas;
mod plugins;
mod push;
mod relaunch;
mod report;
mod rooms;
mod routines;
mod skills;
mod threads;

use topcoat::router::RouterBuilder;

/// Adds every area's routes.
pub(crate) fn routes(b: RouterBuilder) -> RouterBuilder {
    let b = devices::routes(b);
    let b = folders::routes(b);
    let b = logins::routes(b);
    let b = mcp::routes(b);
    let b = pairing::routes(b);
    let b = personas::routes(b);
    let b = plugins::routes(b);
    let b = push::routes(b);
    let b = relaunch::routes(b);
    let b = report::routes(b);
    let b = rooms::routes(b);
    let b = routines::routes(b);
    let b = skills::routes(b);
    threads::routes(b)
}
